import { submitJob } from '@projexlight/sdk-parsing';
const { job_id } = await submitJob({
  tenant_id, source_blob_id,
  stages: ['ocr','layout','extract:auto-claims'],
});

subscribeEvents('media.blob.ingested.v1', async (e) => {
  if (e.payload.mime !== 'application/pdf') return;
  await submitJob({ source_blob_id: e.payload.blob_id, stages: ['ocr','layout','extract:auto-claims'] });
});

// auto-triggered by the parser; reviewer resolves:
import { resolveReview } from '@projexlight/sdk-parsing';
await resolveReview({
  review_task_id, corrected_value: '1HGBH41JXMN109186',
  resolver_persona_id, decision: 'corrected',
});

subscribeEvents('taxonomy.version.published.v1', async (e) => {
  if (await tenantOptsAutoMigrate({ tenant_id: e.tenant_id })) {
    await reRunExtractStageForRecentJobs({ taxonomy_version: e.payload.version });
  }
});
